effect.shader:
vec4 fxPortOutput;

vec4 fxPortSample(sampler2D image, vec2 uv) {
    vec4 color = texture2D(image, uv);
    if (color.a > 0.0) color.rgb /= color.a;
    else color.rgb = vec3(0.0);
    return color;
}

void fxPortMain() {
    vec2 uv = clamp(acScreenNorm, 0.0, 1.0);
    vec4 original = fxPortSample(inputImg.texture, uv);
    float amount = clamp(1.0 + uControl2, -1.0, 1.0);
    vec2 center = vec2(0.5) + 0.5 * vec2(uControl3, uControl4);
    float scaleX = min(exp2(uControl5), 1.0);
    float scaleY = uControl7 > 0.5 ? min(exp2(uControl6), 1.0) : scaleX;
    vec2 offset = uv - center;
    float radius = length(2.0 * offset / (vec2(scaleX, scaleY) + vec2(0.0001)));
    vec2 sourceUv = uv;
    if (radius < 1.0) {
        float factor = 1.0 - 0.8 * amount * cos(1.57079632679 * radius);
        sourceUv = center + offset * factor;
    }
    vec4 warped = fxPortSample(inputImg.texture, clamp(sourceUv, 0.0, 1.0));
    fxPortOutput = clamp(mix(original, warped, clamp(uControl1, 0.0, 1.0)), 0.0, 1.0);
}

void main() {
    fxPortMain();
    gl_FragColor = vec4(fxPortOutput.rgb * fxPortOutput.a, fxPortOutput.a);
}
